package org.telegram.ui;

import android.content.Context;
import android.graphics.Color;
import android.text.TextUtils;
import android.view.*;
import android.widget.*;
import androidx.recyclerview.widget.*;
import org.telegram.messenger.*;
import org.telegram.messenger.browser.Browser;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.Cells.TextCheckCell;
import org.telegram.ui.Components.*;
import java.util.*;

/** Reference inbox hierarchy: three sections, native cards, complete text and popup controls. */
public final class DevGramNoticesSheet {
    private static final String[] NAMES={"Активность","Новости","Прочее"};
    private static final String[] ABOUT={"Чужие действия: лайки, точки, комментарии","Обновления и новые возможности","Напоминания и служебное"};
    private DevGramNoticesSheet(){}
    private static int dp(float v){return AndroidUtilities.dp(v);}
    private static String t(String text){return DevGramLocale.text(text);}
    private static TextView text(BaseFragment host,String value,int size,boolean bold){TextView v=DevGramStudioControls.text(host.getParentActivity(),"",size,bold,host.getResourceProvider());v.setText(value);return v;}
    private static boolean valid(BaseFragment host,long uid){return host.getParentActivity()!=null&&host.getUserConfig().getClientUserId()==uid&&DevGramCustomizationNotices.allowed();}
    private static BottomSheet sheet(BaseFragment host,String title,View content){BottomSheet sheet=new BottomSheet.Builder(host.getParentActivity(),false,host.getResourceProvider()).setTitle(t(title)).setCustomView(content).create();sheet.fixNavigationBarKey(Theme.key_windowBackgroundWhite);return sheet;}
    private static void watch(BaseFragment host,BottomSheet sheet,Runnable render){long uid=host.getUserConfig().getClientUserId();Runnable policy=()->{if(!valid(host,uid))sheet.dismiss();else render.run();};DevGramProfilePolicy.listen(policy);DevGramCustomizationNotices.listen(render);host.showDialog(sheet,d->{DevGramCustomizationNotices.forget(render);DevGramProfilePolicy.unlisten(policy);});}
    private static TextView row(BaseFragment host,String title,Runnable click){TextView v=text(host,t(title),15,true);v.setPadding(dp(22),dp(16),dp(22),dp(16));v.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,host.getResourceProvider()));v.setBackground(Theme.createSelectorDrawable(Theme.getColor(Theme.key_listSelector,host.getResourceProvider()),2));v.setOnClickListener(x->click.run());return v;}
    public static void show(BaseFragment host){if(host==null||host.getParentActivity()==null||!DevGramProfileCustomization.enabled()||!DevGramAppearanceAccess.check(host,"profile.notices"))return;DevGramCustomizationNotices.wake(host.getCurrentAccount());LinearLayout body=DevGramStudioControls.column(host.getParentActivity());LinearLayout sections=DevGramStudioControls.column(host.getParentActivity());body.addView(sections);body.addView(row(host,"Настройки уведомлений",()->settings(host)));TextView write=row(host,"Написать новость",()->editor(host));body.addView(write);write.setVisibility(DevGramBadges.hasDeveloperFeatures(host.getUserConfig().getClientUserId())?View.VISIBLE:View.GONE);BottomSheet sheet=sheet(host,"Уведомления",body);
        Runnable render=()->{write.setVisibility(DevGramBadges.hasDeveloperFeatures(host.getUserConfig().getClientUserId())?View.VISIBLE:View.GONE);sections.removeAllViews();for(int i=0;i<3;i++){final int category=i;LinearLayout line=new LinearLayout(host.getParentActivity());line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(dp(16),dp(12),dp(16),dp(12));ImageView icon=new ImageView(host.getParentActivity());icon.setImageResource(new int[]{R.drawable.msg_reactions,R.drawable.msg_channel,R.drawable.msg_settings}[i]);icon.setScaleType(ImageView.ScaleType.CENTER);icon.setColorFilter(Theme.getColor(DevGramCustomizationNotices.unread(i)>0?Theme.key_windowBackgroundWhiteBlueText:Theme.key_windowBackgroundWhiteGrayIcon,host.getResourceProvider()));line.addView(icon,LayoutHelper.createLinear(40,40));LinearLayout words=DevGramStudioControls.column(host.getParentActivity());LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,-2,1);wp.leftMargin=dp(12);line.addView(words,wp);words.addView(text(host,t(NAMES[i]),15,true));ArrayList<DevGramCustomizationNotices.Item> items=DevGramCustomizationNotices.of(i);TextView about=text(host,items.isEmpty()?t(ABOUT[i]):items.get(0).title(),13,false);about.setSingleLine();about.setEllipsize(TextUtils.TruncateAt.END);about.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,host.getResourceProvider()));words.addView(about);int unread=DevGramCustomizationNotices.unread(i);if(unread>0){TextView count=text(host,Integer.toString(unread),12,false);count.setTextColor(Color.WHITE);count.setGravity(Gravity.CENTER);count.setPadding(dp(6),dp(1),dp(6),dp(1));count.setBackground(Theme.createRoundRectDrawable(dp(10),Theme.getColor(Theme.key_featuredStickers_addButton,host.getResourceProvider())));line.addView(count);}line.setOnClickListener(v->section(host,category));sections.addView(line);}if(DevGramCustomizationNotices.error()!=null)sections.addView(row(host,"Не удалось загрузить уведомления. Повторить",()->DevGramCustomizationNotices.refresh(true)));};render.run();watch(host,sheet,render);DevGramCustomizationNotices.refresh(true);
    }
    public static void section(BaseFragment host,int category){if(!DevGramCustomizationNotices.allowed()||host.getParentActivity()==null)return;LinearLayout body=DevGramStudioControls.column(host.getParentActivity());RecyclerListView list=new RecyclerListView(host.getParentActivity(),host.getResourceProvider()){@Override protected void onMeasure(int w,int h){super.onMeasure(w,DevGramStudioControls.sheetHeightSpec(h,.72f));}};list.setLayoutManager(new LinearLayoutManager(host.getParentActivity()));list.setBackgroundColor(Theme.getColor(Theme.key_windowBackgroundGray,host.getResourceProvider()));list.setPadding(0,dp(4),0,dp(8));list.setClipToPadding(false);NoticeAdapter adapter=new NoticeAdapter(host,category);list.setAdapter(adapter);body.addView(list);TextView more=row(host,"Загрузить ещё",()->DevGramCustomizationNotices.section(category,true));body.addView(more);TextView write=row(host,"Написать новость",()->editor(host));if(category==1)body.addView(write);BottomSheet sheet=sheet(host,NAMES[category],body);
        Runnable render=()->{write.setVisibility(DevGramBadges.hasDeveloperFeatures(host.getUserConfig().getClientUserId())?View.VISIBLE:View.GONE);adapter.replace(DevGramCustomizationNotices.of(category));more.setVisibility(DevGramCustomizationNotices.more(category)?View.VISIBLE:View.GONE);more.setEnabled(!DevGramCustomizationNotices.busy());if(DevGramCustomizationNotices.error()!=null){more.setVisibility(View.VISIBLE);more.setText(t("Не удалось загрузить уведомления. Повторить"));more.setOnClickListener(v->DevGramCustomizationNotices.section(category,false));}else{more.setText(t("Загрузить ещё"));more.setOnClickListener(v->DevGramCustomizationNotices.section(category,true));}DevGramCustomizationNotices.markRead(category);};render.run();watch(host,sheet,render);DevGramCustomizationNotices.section(category,false);
    }
    private static String when(long timestamp){long elapsed=Math.max(0,System.currentTimeMillis()/1000-timestamp);if(elapsed<60)return t("сейчас");if(elapsed<3600)return elapsed/60+t(" мин");if(elapsed<86400)return elapsed/3600+t(" ч");if(elapsed<172800)return t("вчера");return elapsed/86400+t(" дн");}
    private static final class Entry {final DevGramCustomizationNotices.Item value;final String signature;final long key;Entry(DevGramCustomizationNotices.Item item){value=item;key=item==null?0:item.id;signature=item==null?Boolean.toString(DevGramCustomizationNotices.loading()):item.title()+item.text()+item.articleUrl+item.nativeArticle+item.coverMessage+item.cover+item.fresh()+when(item.ts)+DevGramBadges.hasDeveloperFeatures(DevGramCustomizationNotices.viewer());}}
    private static final class NoticeAdapter extends RecyclerListView.SelectionAdapter {
        final BaseFragment host;final int category;ArrayList<Entry> rows=new ArrayList<>();NoticeAdapter(BaseFragment host,int category){this.host=host;this.category=category;rows.add(new Entry(null));}
        void replace(ArrayList<DevGramCustomizationNotices.Item> values){ArrayList<Entry> old=rows,next=new ArrayList<>();for(DevGramCustomizationNotices.Item value:values)next.add(new Entry(value));if(next.isEmpty())next.add(new Entry(null));DiffUtil.DiffResult diff=DiffUtil.calculateDiff(new DiffUtil.Callback(){public int getOldListSize(){return old.size();}public int getNewListSize(){return next.size();}public boolean areItemsTheSame(int a,int b){return old.get(a).key==next.get(b).key;}public boolean areContentsTheSame(int a,int b){return old.get(a).signature.equals(next.get(b).signature);}});rows=next;diff.dispatchUpdatesTo(this);}
        @Override public boolean isEnabled(RecyclerView.ViewHolder h){return false;}@Override public int getItemCount(){return rows.size();}
        @Override public RecyclerView.ViewHolder onCreateViewHolder(ViewGroup parent,int type){LinearLayout container=DevGramStudioControls.column(parent.getContext());container.setLayoutParams(new RecyclerView.LayoutParams(-1,-2));return new RecyclerListView.Holder(container);}
        @Override public void onBindViewHolder(RecyclerView.ViewHolder holder,int position){LinearLayout container=(LinearLayout)holder.itemView;container.removeAllViews();if(rows.get(position).value==null){TextView empty=text(host,t(DevGramCustomizationNotices.loading()?"Загружаю…":category==0?"Пока пусто. Здесь появится то, что другие делают с вашим профилем: лайки, точки на полотне, комментарии.":category==1?"Пока пусто. Здесь появятся обновления и новые возможности DevGram.":"Пока пусто. Здесь появится служебное: напоминания и предупреждения."),14,false);empty.setPadding(dp(16),dp(14),dp(16),dp(18));container.addView(empty);return;}DevGramCustomizationNotices.Item item=rows.get(position).value;LinearLayout card=DevGramStudioControls.column(container.getContext());card.setPadding(dp(14),dp(14),dp(14),dp(12));card.setBackground(Theme.createRoundRectDrawable(dp(10),Theme.getColor(Theme.key_windowBackgroundWhite,host.getResourceProvider())));LinearLayout top=new LinearLayout(container.getContext());FrameLayout face=new FrameLayout(container.getContext());face.addView(DevGramNoticePopup.face(host,item.who,36),LayoutHelper.createFrame(-1,-1));if(item.who<=0&&item.fresh()){View dot=new View(container.getContext());dot.setBackground(Theme.createCircleDrawable(dp(6),Theme.getColor(Theme.key_featuredStickers_addButton,host.getResourceProvider())));face.addView(dot,LayoutHelper.createFrame(6,6,Gravity.RIGHT|Gravity.TOP));}top.addView(face,LayoutHelper.createLinear(36,36));LinearLayout words=DevGramStudioControls.column(container.getContext());LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,-2,1);wp.leftMargin=dp(10);top.addView(words,wp);if(canDelete(host,item)){ImageView remove=new ImageView(container.getContext());remove.setImageResource(R.drawable.msg_delete);remove.setScaleType(ImageView.ScaleType.CENTER);remove.setColorFilter(Theme.getColor(Theme.key_windowBackgroundWhiteGrayIcon,host.getResourceProvider()));remove.setContentDescription(t("Удалить новость"));remove.setBackground(Theme.createSelectorDrawable(Theme.getColor(Theme.key_listSelector,host.getResourceProvider()),2));remove.setOnClickListener(v->delete(host,item));top.addView(remove,LayoutHelper.createLinear(44,44));}words.addView(text(host,item.title(),15,true));TextView time=text(host,when(item.ts),12,false);time.setPadding(0,dp(3),0,0);time.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,host.getResourceProvider()));words.addView(time);card.addView(top);if(!item.cover.isEmpty()||item.coverMessage>0){BackupImageView image=new BackupImageView(container.getContext());image.setRoundRadius(dp(12));image.getImageReceiver().setAllowStartAnimation(false);if(item.coverMessage>0)DevGramNativeNews.cover(image,host.getCurrentAccount(),item.coverMessage,item.id);else image.setImage(item.cover,"800_450",null);image.setContentDescription(item.title());LinearLayout.LayoutParams imageParams=new LinearLayout.LayoutParams(-1,dp(150));imageParams.topMargin=dp(12);card.addView(image,imageParams);}TextView body=text(host,item.text(),14,false);body.setMaxLines(4);body.setEllipsize(TextUtils.TruncateAt.END);body.setPadding(0,dp(10),0,0);if(!item.text().isEmpty())card.addView(body);TextView read=text(host,t(item.articleUrl.isEmpty()&&item.nativeArticle.isEmpty()?"Читать полностью":"Читать статью"),13,true);read.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,host.getResourceProvider()));read.setPadding(0,dp(15),0,dp(5));card.addView(read);body.post(()->{android.text.Layout layout=body.getLayout();read.setVisibility(!item.articleUrl.isEmpty()||!item.nativeArticle.isEmpty()||layout!=null&&layout.getLineCount()>0&&layout.getEllipsisCount(layout.getLineCount()-1)>0?View.VISIBLE:View.GONE);});card.setOnClickListener(v->item(host,item));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(dp(10),dp(4),dp(10),dp(6));container.addView(card,cp);}
    }
    public static void item(BaseFragment host,DevGramCustomizationNotices.Item item){if(host.getParentActivity()==null||!DevGramCustomizationNotices.allowed())return;if(!item.nativeArticle.isEmpty()){DevGramNativeNews.read(host,item.id);return;}if(!item.articleUrl.isEmpty()){Browser.openUrl(host.getParentActivity(),item.articleUrl,true,true);return;}LinearLayout body=DevGramStudioControls.column(host.getParentActivity());body.setPadding(dp(16),dp(8),dp(16),dp(20));TextView title=text(host,item.title(),20,true);title.setTextIsSelectable(true);body.addView(title);TextView date=text(host,java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.MEDIUM,java.text.DateFormat.SHORT).format(new Date(item.ts*1000)),12,false);date.setPadding(0,dp(8),0,0);date.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,host.getResourceProvider()));body.addView(date);TextView words=text(host,item.text(),16,false);words.setPadding(0,dp(16),0,0);words.setTextIsSelectable(true);body.addView(words);ScrollView scroll=new ScrollView(host.getParentActivity());scroll.addView(body);BottomSheet sheet=sheet(host,"Уведомление",scroll);watch(host,sheet,()->{});}
    private static boolean canDelete(BaseFragment host,DevGramCustomizationNotices.Item item){long uid=host.getUserConfig().getClientUserId();return item.code.equals("news")&&item.who==uid&&DevGramBadges.hasDeveloperFeatures(uid);}
    private static void delete(BaseFragment host,DevGramCustomizationNotices.Item item){
        long uid=host.getUserConfig().getClientUserId();if(!valid(host,uid)||!canDelete(host,item))return;
        new AlertDialog.Builder(host.getParentActivity(),host.getResourceProvider()).setTitle(t("Удалить новость?")).setMessage(t("Новость исчезнет у всех читателей. Статья и её черновик будут удалены. Отменить удаление нельзя."))
            .setPositiveButton(t("Удалить"),(d,w)->{if(!valid(host,uid)||!canDelete(host,item))return;try{DevGramProfilePolicy.request(host.getCurrentAccount(),"studio/notices/delete",new org.json.JSONObject().put("id",item.id).put("confirm",true),(result,error)->{
                if(!valid(host,uid))return;if(result==null){BulletinFactory.of(host).createErrorBulletin(t("Не удалось удалить. Обновите список и попробуйте ещё раз.")).show();return;}
                DevGramCustomizationNotices.removed(host.getCurrentAccount(),item.id,item.nativeArticle);BulletinFactory.of(host).createSimpleBulletin(R.raw.contact_check,t("Новость удалена")).show();
            });}catch(Exception ignored){}}).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).show();
    }
    private static void editor(BaseFragment host){if(valid(host,host.getUserConfig().getClientUserId())&&DevGramBadges.hasDeveloperFeatures(host.getUserConfig().getClientUserId()))host.presentFragment(new DevGramNewsEditorActivity());}
    private static void settings(BaseFragment host){LinearLayout body=DevGramStudioControls.column(host.getParentActivity());header(host,body,"Как показывать");check(host,body,"Полные уведомления",DevGramCustomizationNotices.full(),DevGramCustomizationNotices::full);note(host,body,"Обычно вести всплывают пузырьком, и только новости разворачиваются во всю ширину. Включите — и разворачиваться будут все.");header(host,body,"О чём сообщать");String[] codes={"like","canvas","comment","work","news","rest"},names={"Лайкнули профиль","Рисуют на полотне","Комментируют","Лайкнули работу","Новости DevGram","Служебное"};for(int i=0;i<codes.length;i++){String code=codes[i];check(host,body,names[i],DevGramCustomizationNotices.pops(code),value->DevGramCustomizationNotices.pops(code,value));}note(host,body,"Выключенное не всплывает, но остаётся в списке уведомлений. Колокольчик продолжает считать непрочитанное.");ScrollView scroll=new ScrollView(host.getParentActivity());scroll.addView(body);watch(host,sheet(host,"Настройки уведомлений",scroll),()->{});}
    private static void header(BaseFragment host,LinearLayout body,String label){TextView title=text(host,t(label),14,true);title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueHeader,host.getResourceProvider()));title.setPadding(dp(22),dp(18),dp(22),dp(10));body.addView(title);}
    private static void note(BaseFragment host,LinearLayout body,String label){TextView note=text(host,t(label),13,false);note.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,host.getResourceProvider()));note.setPadding(dp(24),dp(4),dp(24),dp(14));body.addView(note);}
    private static void check(BaseFragment host,LinearLayout body,String label,boolean value,java.util.function.Consumer<Boolean> done){TextCheckCell cell=new TextCheckCell(host.getParentActivity(),host.getResourceProvider());cell.setTextAndCheck(t(label),value,false);cell.setOnClickListener(v->{if(!DevGramCustomizationNotices.allowed())return;boolean selected=!cell.isChecked();cell.setChecked(selected);done.accept(selected);});body.addView(cell);}
}
